#!/usr/bin/env python3
"""一次性修复：两篇整字段错语种（突尼斯 es §0 是阿拉伯语正文、卡萨布兰卡 pt §3 是俄语词块串联），按英文原文整节重写为西语/葡语。

断言关键事实 + 断言原文确有外文残留（避免误覆盖），fail-closed。
"""
import json
import re

CYR = re.compile(r"[а-яА-ЯёЁ]")
ARAB = re.compile(r"[\u0600-\u06ff]")

TUNISIA_HEADING_ES = "Regulación de importación de fijaciones en Túnez y cumplimiento normativo"
TUNISIA_ES = """Esta guía de exportación de fijaciones al Mediterráneo tunecino describe las barreras regulatorias críticas que los fabricantes chinos de fijaciones deben resolver antes de enviar pernos, tuercas, espárragos y componentes roscados industriales a territorio tunecino. Túnez aplica un marco formal de verificación previa a la importación gestionado por la Dirección General de Comercio Exterior, que exige a los importadores obtener la documentación de despacho correspondiente para todas las fijaciones metálicas industriales antes de la llegada de la carga [1]. A diferencia de muchos mercados de África Occidental, Túnez no impone prohibiciones generales de importación sobre fijaciones de acero, pero aplica licencias selectivas a las calidades de acero aleado de alta resistencia utilizadas en proyectos de infraestructura y energía. Los responsables de compras de las distribuidoras tunecinas informan de forma constante de retenciones en puerto cuando los exportadores descuidan los trámites de certificación habituales, lo que se traduce en costes de almacenamiento, retrasos de inspección y posibles rechazos de carga.
<p>Las normas obligatorias de producto constituyen la base de los protocolos locales de cumplimiento. ISO 898-1 e ISO 898-2 siguen siendo la referencia principal para las fijaciones mecánicas de acero al carbono y acero aleado, y definen los requisitos de resistencia a la tracción para pernos de clase 8.8, 10.9 y 12.9 [4]. Aunque Túnez no exige una certificación obligatoria de producto local, los grandes compradores industriales que abastecen proyectos de automoción y construcción exigen informes de ensayo completos alineados con estas especificaciones ISO para satisfacer a sus clientes europeos. El marcado CE no es legalmente obligatorio para la importación directa a Túnez, pero el material destinado a reexportación hacia Estados miembros de la UE debe contar con documentación válida de conformidad CE. Los acabados superficiales son otro punto habitual de conflicto: las fijaciones galvanizadas en caliente (HDG) se prefieren claramente frente a las galvanizadas electrolíticamente en la infraestructura costera de Susa y Sfax, donde la humedad salina acelera la oxidación superficial. Los recubrimientos de zinc electrolítico suelen no cumplir las expectativas de los compradores locales en cuanto a vida útil exterior, incluso cuando la resistencia mecánica alcanza los valores ISO.</p>
<p>La documentación aduanera exige una coherencia rigurosa en cada conjunto de documentos presentado. Los exportadores deben aportar facturas comerciales con declaración de origen, listas de embalaje detalladas, conocimiento de embarque marítimo completo y un certificado de origen oficial emitido y visado por cámara en China [1]. La aduana tunecina coteja descripciones de producto, códigos HS, pesos y valores en todos los documentos; incluso discrepancias textuales menores activan una inspección manual prolongada en las terminales portuarias. Los procedimientos de inspección de calidad en el puerto de Radès incluyen muestreo aleatorio de los envíos contenerizados de fijaciones, centrado en la precisión dimensional, la verificación de la calidad del material y la comprobación del espesor del recubrimiento. Los exportadores deben preparar una lista de verificación de cumplimiento que cubra certificados de ensayo ISO, certificados de material de laminación, informes de inspección de recubrimiento y la documentación original de origen antes de la salida del buque. Entre los materiales restringidos figuran las fijaciones fabricadas con aditivos de aleación de plomo por encima de los umbrales permitidos, en línea con las directrices REACH de la UE adoptadas voluntariamente por la mayoría de las zonas industriales tunecinas.</p>"""

MOROCCO_PT = """<p>O procedimento de importação de fixadores pelo porto de Casablanca, em Marrocos, cruza-se com requisitos de conformidade rigorosos concebidos para proteger a segurança pública nas aplicações de construção, infraestrutura e indústria. O quadro regulamentar marroquino obriga a que o hardware industrial importado cumpra ou exceda as especificações estabelecidas pela Normalisation et Certification (MN), alinhadas de perto com as normas ISO e EN [4].</p><p>Normas industriais marroquinas para fixadores</p><p>Os fixadores utilizados em aplicações estruturais — construção de pontes, estruturas de edifícios comerciais, infraestruturas com qualificação sísmica — devem cumprir as normas NM, que reproduzem a EN 14399 (conjuntos de aparafusamento estrutural de alta resistência) ou especificações ASTM como a F1554 para pernos de ancoragem [5]. A justificação é crítica do ponto de vista da engenharia: a falha de um fixador estrutural cria o risco de colapso catastrófico. O código de construção marroquino de 2011 (RPS 2011) remete explicitamente para requisitos de conceção sísmica que dependem de características adequadas de resistência e ductilidade dos fixadores [4]. Os importadores devem demonstrar que os pernos de ancoragem têm um limite de elasticidade mínimo de 36 000 psi (F1554 classe 36) ou 55 000 psi (classe 55), com percentagens de alongamento documentadas.</p><p>Nas aplicações não estruturais — montagem de máquinas, fixação de equipamentos, fabrico geral — os fixadores têm igualmente de cumprir normas de base de material e de dimensão. A ISO 898 define as propriedades mecânicas dos fixadores de aço-carbono e aço-ligado, incluindo carga de prova, dureza e binário [5]. Os fixadores de aço inoxidável devem cumprir a ISO 3506, que especifica as classes de resistência à corrosão (A2 para composição 304, A4 para 316) e as propriedades mecânicas em diferentes condições de temperatura.</p><p>Requisitos de marcação e embalagem</p><p>As autoridades aduaneiras e de fiscalização do mercado marroquinas aplicam os requisitos de marcação previstos nas normas NM. Cada embalagem deve apresentar: designação do produto, classe do material, especificações dimensionais, quantidade e país de origem. Nos envios a granel de fixadores, a etiquetagem das paletes tem de ser visível e durável — etiquetas de polietileno ou painéis de cartão marcados a laser resistem à humidade típica do armazenamento no porto de Casablanca. A marcação ausente ou ilegível obriga a reembalagem às custas do importador antes do desalfandegamento.</p><p>Os tratamentos de superfície dos fixadores exigem documentação específica. Os fixadores galvanizados a quente (espessura mínima de revestimento de 45 μm conforme a ISO 1461) devem especificar o peso do revestimento e fornecer relatórios de ensaio que comprovem a conformidade com os requisitos da ASTM A123 para revestimento de zinco [5]. Para os fixadores eletrogalvanizados com zinco-níquel utilizados em aplicações automóveis ou eletrónicas, a documentação deve confirmar a espessura do revestimento (tipicamente 8-12 μm) e demonstrar resistência à ferrugem branca conforme a ASTM F1941.</p><p>Processo de inspeção e verificação de conformidade</p><p>O procedimento de importação de fixadores pelo porto de Casablanca inclui inspeção física por funcionários aduaneiros ou organismos de inspeção delegados nos envios assinalados como de alto risco ou sem certificados de conformidade reconhecidos [2]. Os inspetores verificam: precisão dimensional por medição com paquímetro face às tolerâncias da especificação, estado da superfície (sem defeitos de revestimento nem danos na rosca), legibilidade da marcação e integridade da embalagem. As inspeções reprovadas resultam em ordens de reexportação ou destruição — nenhum dos desfechos é aceitável para operações de cadeia de abastecimento B2B.</p><p>Os responsáveis de compras devem estabelecer protocolos de controlo de qualidade à entrada no porto de Casablanca. Vale a pena nomear um agente de inspeção local para assistir às inspeções aduaneiras e coordenar com as autoridades portuárias uma ação corretiva imediata caso surjam discrepâncias. Esta abordagem proativa reduz os atrasos no desalfandegamento e protege contra cenários dispendiosos de reenvio.</p>"""

JOBS = [
    ("tunisia-mediterranean-fastener-export-guide", 0, "es", TUNISIA_HEADING_ES, TUNISIA_ES, ARAB,
     ["ISO 898-1", "8.8", "10.9", "12.9", "Radès", "REACH"]),
    ("morocco-casablanca-port-fastener-import-procedure", 3, "pt", None, MOROCCO_PT, CYR,
     ["EN 14399", "F1554", "RPS 2011", "36 000 psi", "ISO 1461", "ASTM F1941", "ISO 3506"]),
]

for slug, sec, lang, new_head, new_body, script_re, must in JOBS:
    path = "content/articles/%s.json" % slug
    art = json.load(open(path))
    s = art["sections"][sec]
    old_body = s["body"][lang]
    assert script_re.search(old_body), "%s §%d 原字段没有外文残留，拒绝覆盖" % (slug, sec)
    if new_head:
        assert script_re.search(s["heading"][lang]), "%s heading 没有外文残留" % slug
        s["heading"][lang] = new_head
    for m in must:
        assert m in new_body, "%s 译文缺关键事实：%s" % (slug, m)
    assert not script_re.search(new_body), "%s 译文仍有外文" % slug
    s["body"][lang] = new_body
    open(path, "w").write(json.dumps(art, ensure_ascii=False, indent=2) + "\n")
    print("✓ %s §%d %s 重写 %d→%d 字符" % (slug, sec, lang, len(old_body), len(new_body)))
